package.description:
Chromium fork for Windows named after radioactive element No. 90;

• Always built with the latest stable version of Chromium.
i686

version.file:
for /f "delims=" %%x in ('dir /b *.exe') do set setup=%%x "%setup%" /extract:
move disk1.cab .Npackd
call "%npackdih%\InstallMSI.bat" INSTALLDIR yes

for /f "delims=" %%x in ('dir /b *.exe') do set setup=%%x "%setup%" /extract:
move disk1.cab .Npackd
call "%npackdih%\InstallMSI.bat" INSTALLDIR yes

try {
    var fs = new ActiveXObject("Scripting.FileSystemObject");              
    var sh = WScript.CreateObject("WScript.Shell");                        
    var lib = eval(fs.OpenTextFile(                                        
             sh.ExpandEnvironmentStrings("%NIH%") + "\\Lib.js", 1).ReadAll()); 
     
    lib.installerHelper = sh.ExpandEnvironmentStrings("%NIH%");                                                                  
    lib.unpackAndDelete(lib.findFile(".", /\.7z$/i), ".");
    lib.unpackAndDelete(lib.findDir(".", /^cgminer-/i), ".");
} catch (e) {
    WScript.Echo(e.name + ": " + e.message);
    WScript.Echo(e.number + ": " + e.description);
    WScript.Quit(1);
}

var fs = new ActiveXObject("Scripting.FileSystemObject");
var sh = WScript.CreateObject("WScript.Shell");
var lib = eval(fs.OpenTextFile(
      sh.ExpandEnvironmentStrings("%NIH%") + "\\Lib.js", 1).ReadAll());

lib.addPropertyToMSI("advinst.msi", "APPDIR", "C:\\");

@echo.
@echo Setting up 32-bit environment for using DMD 2 from %~dp0\windows\bin.
@set PATH=%~dp0\windows\bin;%PATH%

var shell = new ActiveXObject("WScript.Shell"); 
var dir = shell.CurrentDirectory;
var menu = shell.SpecialFolders("AllUsersStartMenu"); 

var fso = new ActiveXObject("Scripting.FileSystemObject");
if (!fso.FolderExists(menu + "\\D"))
    fso.CreateFolder(menu + "\\D");

var s = shell.CreateShortcut(menu + "\\D\\D2 32-bit Command Prompt.lnk"); 
s.TargetPath = "%comspec%";
s.Arguments = "/K \"" + dir + "\\dmd2vars32.bat\"";
s.Save(); 

s = shell.CreateShortcut(menu + "\\D\\D2 Documentation.lnk"); 
s.TargetPath = dir + "\\html\\d\\index.html";
s.Save(); 

s = shell.CreateShortcut(menu + "\\D\\D2 HTML Documentatio.lnk"); 
s.TargetPath = dir + "\\windows\\bin\\d.chm";
s.Save();

var shell = new ActiveXObject("WScript.Shell"); 
var menu = shell.SpecialFolders("AllUsersStartMenu"); 
var fso = new ActiveXObject("Scripting.FileSystemObject");

function deleteIfExists(f) {
    if (fso.FileExists(f))
        fso.DeleteFile(f, true);
}

deleteIfExists(menu + "\\D\\D2 32-bit Command Prompt.lnk");
deleteIfExists(menu + "\\D\\D2 Documentation.lnk");
deleteIfExists(menu + "\\D\\D2 HTML Documentatio.lnk");

if (fso.FolderExists(menu + "\\D")) {
    var f = fso.GetFolder(menu + "\\D");
    if (new Enumerator(f.SubFolders).atEnd() && new Enumerator(f.Files).atEnd())
        f.Delete(true);
}

